package io.github.jaruizes.proposal.infrastructure.persistence;
import io.github.jaruizes.proposal.domain.model.*; import io.github.jaruizes.proposal.domain.ports.*; import io.github.jaruizes.proposal.infrastructure.persistence.repository.*; import org.springframework.stereotype.Component; import java.util.*;
@Component public class PostgresPersistenceAdapter implements OfferRepositoryPort,PhaseRepositoryPort,ArtifactRepositoryPort,AgentExecutionRepositoryPort { private final SpringOfferRepository offers;private final SpringPhaseRepository phases;private final SpringArtifactRepository artifacts;private final SpringAgentExecutionRepository executions; public PostgresPersistenceAdapter(SpringOfferRepository o,SpringPhaseRepository p,SpringArtifactRepository a,SpringAgentExecutionRepository e){offers=o;phases=p;artifacts=a;executions=e;}
 public Offer save(Offer o){return PersistenceMapper.toDomain(offers.save(PersistenceMapper.toEntity(o)));} public Optional<Offer> findById(UUID id){return offers.findById(id).map(PersistenceMapper::toDomain);} public List<Offer> findAll(){return offers.findAll().stream().map(PersistenceMapper::toDomain).toList();}
 public PhaseExecution save(PhaseExecution p){return PersistenceMapper.toDomain(phases.save(PersistenceMapper.toEntity(p)));} public Optional<PhaseExecution> find(UUID offerId,PhaseType phase){return phases.findByOfferIdAndPhase(offerId,phase.name()).map(PersistenceMapper::toDomain);} public List<PhaseExecution> findByOfferId(UUID offerId){return phases.findByOfferId(offerId).stream().map(PersistenceMapper::toDomain).toList();}
 public Artifact save(Artifact a){return PersistenceMapper.toDomain(artifacts.save(PersistenceMapper.toEntity(a)));} public List<Artifact> findByOfferId(UUID offerId){return artifacts.findByOfferIdOrderByCreatedAtAsc(offerId).stream().map(PersistenceMapper::toDomain).toList();} public Optional<Artifact> findLatest(UUID offerId,ArtifactType type){return artifacts.findFirstByOfferIdAndTypeOrderByVersionDesc(offerId,type.name()).map(PersistenceMapper::toDomain);} public int nextVersion(UUID offerId,ArtifactType type){return (int)artifacts.countByOfferIdAndType(offerId,type.name())+1;}
 public AgentExecution save(AgentExecution a){return PersistenceMapper.toDomain(executions.save(PersistenceMapper.toEntity(a)));} public List<AgentExecution> findByOfferId(UUID offerId){return executions.findByOfferIdOrderByStartedAtAsc(offerId).stream().map(PersistenceMapper::toDomain).toList();}
}
